}

.chat-detail-screen .chat-header-title{
  font-size:var(--chat-header-title-size) !important;
  white-space:nowrap !important;
  overflow:hidden !important;
  text-overflow:ellipsis !important;
  text-align:center !important;
}

/* 四个按钮不许被压缩 */
.chat-detail-screen :is(.header-btn-back,.header-btn-phone,.header-btn-video,.header-btn-info){
  flex:none !important;
}

/* 对方输入中：动画图按 15px 等比缩小，不裁切 */
#chat-detail-screen:has(.nuo-typing-indicator) .header-profile-section,
#chat-detail-screen:has(.nuo-typing-indicator) .header-profile-section > *{
