}

/* ===== 电话按钮把位置让给标题，自己浮在标题上面（看不见，仍可点） ===== */
:root{
  --nj-hd-title-shift:44px;   /* 电话让位后，居中要用的数值从 80 变成了 44 */
}

.chat-detail-screen .header-btn-phone{
  margin-left:-36px !important;   /* 和按钮宽度一样：占位变成 0，按钮仍在原来的位置 */
  position:relative !important;
  z-index:5 !important;           /* 层级高于标题 */
}

/* ===== 标题宽度硬上限：长名字只能用省略号，不再挤右边按钮 ===== */
:root{
  --nj-hd-reserve:150px;   /* 两边按钮 + 边距占的总宽度：按钮还被挤就加大，省略号出现得太早就减小 */
}

.chat-detail-screen .header-profile-section{
  max-width:calc(100vw - var(--nj-hd-reserve)) !important;
}
.chat-detail-screen .header-profile-section .chat-header-title{
  max-width:calc(100vw - var(--nj-hd-reserve)) !important;
  overflow:hidden !important;
  text-overflow:ellipsis !important;
  white-space:nowrap !important;
}

