}

.chat-detail-screen .msg-translation-detached-them {
  align-self: flex-start !important;
  margin-left: 20px !important; 
}
.chat-detail-screen .msg-translation-detached-me {
  align-self: flex-end !important;
  margin-right: 20px !important;
} 

/* =======================================
   8️⃣ 思维链定制 (诗意文案)
   ======================================= */
.chat-detail-screen {
  /* 按钮文字、箭头、展开后的正文，全都变成静谧灰蓝 */
